ALTER TABLE launch_rounds ADD COLUMN level INTEGER NOT NULL DEFAULT 1 CHECK(level IN(1,2));
CREATE TABLE phase2_sessions(round_id TEXT PRIMARY KEY REFERENCES launch_rounds(id) ON DELETE CASCADE,stage TEXT NOT NULL CHECK(stage IN('briefing','round_a','swap','round_b','review','completed')),leg INTEGER NOT NULL DEFAULT 1 CHECK(leg IN(1,2)),private_case TEXT NOT NULL CHECK(json_valid(private_case)),opened_at INTEGER NOT NULL,launch_at INTEGER NOT NULL,start_at INTEGER,deadline_at INTEGER,paused_at INTEGER,duration_seconds INTEGER NOT NULL DEFAULT 600 CHECK(duration_seconds BETWEEN 60 AND 1800),winner TEXT CHECK(winner IN('red','blue','draw')),grades TEXT CHECK(grades IS NULL OR json_valid(grades)),reason TEXT,completed_at INTEGER);
CREATE TABLE phase2_participants(round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),ready INTEGER NOT NULL DEFAULT 0 CHECK(ready IN(0,1)),PRIMARY KEY(round_id,user_id));
CREATE TABLE phase2_payments(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,leg INTEGER NOT NULL CHECK(leg IN(1,2)),team TEXT NOT NULL CHECK(team IN('red','blue')),title TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 5000000),requester_key TEXT NOT NULL,tenant TEXT NOT NULL,created_by TEXT REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE phase2_policies(round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,leg INTEGER NOT NULL CHECK(leg IN(1,2)),team TEXT NOT NULL CHECK(team IN('red','blue')),policy TEXT NOT NULL CHECK(json_valid(policy)),updated_by TEXT REFERENCES users(id),updated_at INTEGER NOT NULL,PRIMARY KEY(round_id,leg,team));
CREATE TABLE phase2_runs(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,leg INTEGER NOT NULL CHECK(leg IN(1,2)),team TEXT NOT NULL CHECK(team IN('red','blue')),kind TEXT NOT NULL CHECK(kind IN('probe','defense')),actor TEXT NOT NULL REFERENCES users(id),request TEXT NOT NULL CHECK(json_valid(request)),response TEXT NOT NULL CHECK(json_valid(response)),score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),request_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(round_id,actor,request_key));
CREATE TABLE phase2_pins(round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,team TEXT NOT NULL CHECK(team IN('red','blue')),run_id TEXT NOT NULL REFERENCES phase2_runs(id) ON DELETE CASCADE,actor TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,PRIMARY KEY(round_id,team,run_id));
CREATE TABLE phase2_notes(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,team TEXT NOT NULL CHECK(team IN('red','blue')),actor TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 3000),created_at INTEGER NOT NULL);
CREATE TABLE phase2_reports(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES phase2_sessions(round_id) ON DELETE CASCADE,team TEXT NOT NULL CHECK(team IN('red','blue')),actor TEXT NOT NULL REFERENCES users(id),payload TEXT NOT NULL CHECK(json_valid(payload)),submitted_at INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(round_id,actor,request_key));
CREATE INDEX phase2_runs_team ON phase2_runs(round_id,team,created_at DESC);
CREATE INDEX phase2_notes_team ON phase2_notes(round_id,team,created_at DESC);
CREATE INDEX phase2_reports_team ON phase2_reports(round_id,team,submitted_at DESC);
CREATE INDEX phase2_payments_team ON phase2_payments(round_id,leg,team);
CREATE TRIGGER phase2_runs_guard BEFORE INSERT ON phase2_runs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id JOIN phase2_participants a ON a.round_id=p.round_id AND a.user_id=p.user_id WHERE s.round_id=NEW.round_id AND s.stage IN('round_a','round_b') AND s.leg=NEW.leg AND s.paused_at IS NULL AND s.start_at<=NEW.created_at AND s.deadline_at>=NEW.created_at AND p.user_id=NEW.actor AND p.team=NEW.team AND a.ready=1 AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Phase 2 exercise is frozen or unauthorized') END;
 SELECT CASE WHEN (NEW.kind='probe') != ((NEW.leg=1 AND NEW.team='red') OR (NEW.leg=2 AND NEW.team='blue')) THEN RAISE(ABORT,'Phase 2 task not assigned') END;
END;
CREATE TRIGGER phase2_pin_guard BEFORE INSERT ON phase2_pins BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_pins WHERE round_id=NEW.round_id AND team=NEW.team AND run_id=NEW.run_id) AND (SELECT COUNT(*) FROM phase2_pins WHERE round_id=NEW.round_id AND team=NEW.team)>=30 THEN RAISE(ABORT,'Phase 2 team evidence limit') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id JOIN phase2_runs r ON r.round_id=s.round_id AND r.team=p.team WHERE s.round_id=NEW.round_id AND s.stage IN('round_a','round_b') AND s.paused_at IS NULL AND s.start_at<=NEW.created_at AND s.deadline_at>=NEW.created_at AND p.user_id=NEW.actor AND p.team=NEW.team AND r.id=NEW.run_id AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Phase 2 evidence is frozen or unauthorized') END;
END;
CREATE TRIGGER phase2_note_guard BEFORE INSERT ON phase2_notes BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id WHERE s.round_id=NEW.round_id AND s.stage IN('round_a','round_b') AND s.paused_at IS NULL AND s.start_at<=NEW.created_at AND s.deadline_at>=NEW.created_at AND p.user_id=NEW.actor AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Phase 2 notes are frozen or unauthorized') END;
END;
CREATE TRIGGER phase2_report_guard BEFORE INSERT ON phase2_reports BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id WHERE s.round_id=NEW.round_id AND s.stage='round_b' AND s.paused_at IS NULL AND s.start_at<=NEW.submitted_at AND s.deadline_at>=NEW.submitted_at AND p.user_id=NEW.actor AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Phase 2 reports are frozen or unauthorized') END;
END;
CREATE TRIGGER phase2_policy_guard BEFORE UPDATE ON phase2_policies WHEN NEW.updated_by IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id WHERE s.round_id=NEW.round_id AND s.stage IN('round_a','round_b') AND s.leg=NEW.leg AND s.paused_at IS NULL AND s.start_at<=NEW.updated_at AND s.deadline_at>=NEW.updated_at AND p.user_id=NEW.updated_by AND p.team=NEW.team AND u.role='customer' AND u.status='active' AND ((s.leg=1 AND p.team='blue') OR (s.leg=2 AND p.team='red'))) THEN RAISE(ABORT,'Phase 2 policy is frozen or unauthorized') END;
END;
CREATE TRIGGER phase2_payment_guard BEFORE INSERT ON phase2_payments WHEN NEW.created_by IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phase2_sessions s JOIN launch_players p ON p.round_id=s.round_id JOIN users u ON u.id=p.user_id WHERE s.round_id=NEW.round_id AND s.stage IN('round_a','round_b') AND s.leg=NEW.leg AND s.paused_at IS NULL AND s.start_at<=NEW.created_at AND s.deadline_at>=NEW.created_at AND p.user_id=NEW.created_by AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Phase 2 payment is frozen or unauthorized') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM phase2_payments WHERE round_id=NEW.round_id AND leg=NEW.leg AND team=NEW.team)>=20 THEN RAISE(ABORT,'Phase 2 sample payment limit') END;
END;
